with recent_products as (select * from products where category in ('Books', 'Home', 'Fashion') and (brand = 'Umbrella' or cost <= 720)), CostBucketSummary as (select case when cost >= 650 then 'high' when cost >= 270 then 'mid' else 'low' end as cost_bucket, count(case when brand = 'Acme' then 1 end) as acme_count, count(case when category = 'Fashion' then 1 end) as fashion_count from recent_products group by case when cost >= 650 then 'high' when cost >= 270 then 'mid' else 'low' end) select * from CostBucketSummary order by fashion_count desc;
